package pl.edu.ug.cmms;

import org.junit.jupiter.api.Test;

import java.time.LocalDateTime;
import java.nio.file.Files;
import java.nio.file.Path;

import static org.junit.jupiter.api.Assertions.*;
import static pl.edu.ug.cmms.WorkOrder.Priority.HIGH;
import static pl.edu.ug.cmms.WorkOrder.Priority.NORMAL;
import static pl.edu.ug.cmms.WorkOrder.WorkOrderStatus.DONE;
import static pl.edu.ug.cmms.WorkOrder.WorkOrderStatus.OPEN;
import static pl.edu.ug.cmms.WorkOrder.WorkOrderType.BREAKDOWN;
import static pl.edu.ug.cmms.WorkOrder.WorkOrderType.PREVENTIVE;

class AppTest {
    @Test
    void givenWorkOrderInstance_whenDoneWithoutClosedDate_thenThrowsIllegalArgumentException() {
        assertThrows(IllegalArgumentException.class, () -> {
            new WorkOrder("WO-0046",
                    "M-08",
                    PREVENTIVE,
                    NORMAL,
                    DONE,
                    LocalDateTime.parse("2026-03-02T15:45"),
                    null);
        });
    }

    // Sprawdza, czy po zapisaniu obiektu do pliku XML i ponownym jego odczytaniu,
    // nowo powstały obiekt jest dokładnie taki sam jak oryginał (czy żadne pole
    // nie zostało pominięte ani uszkodzone)
    @Test
    void reportCanBeWrittenAndReadBack() throws Exception {
        ReportRecord original = new CmmsStatistics(3).createReport();
        Path file = Files.createTempFile("cmms-report-", ".xml");
        try {
            XmlReportCodec.write(original, file);
            assertEquals(original, XmlReportCodec.read(file));
        } finally {
            Files.deleteIfExists(file);
        }
    }

}
